<?php
require __DIR__.'/bootstrap.php';
$db=db();
$db->exec("CREATE TABLE IF NOT EXISTS administradores (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(160) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, senha_hash VARCHAR(255) NOT NULL, criado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if ((int)$db->query('SELECT COUNT(*) FROM administradores')->fetchColumn()>0) { http_response_code(403); exit('A configuração inicial já foi realizada.'); }
$erro='';
if ($_SERVER['REQUEST_METHOD']==='POST') { check_csrf_admin(); $nome=trim($_POST['nome']??''); $email=strtolower(trim($_POST['email']??'')); $senha=(string)($_POST['senha']??''); if(strlen($nome)<3||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($senha)<12) $erro='Informe nome, e-mail válido e senha com pelo menos 12 caracteres.'; else { $s=$db->prepare('INSERT INTO administradores(nome,email,senha_hash) VALUES(?,?,?)'); $s->execute([$nome,$email,password_hash($senha,PASSWORD_DEFAULT)]); header('Location: login.php?criado=1'); exit; } }
?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Configurar administrador</title><link rel="stylesheet" href="../assets/css/style.css"><body style="padding:30px;background:var(--bg)"><main style="max-width:520px;margin:5vh auto;background:var(--surface);padding:30px;border-radius:18px"><h1>Criar administrador inicial</h1><p>Esta página só funciona enquanto não existir nenhum administrador.</p><?php if($erro):?><p style="color:#b42318"><?=h($erro)?></p><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_admin())?>"><p>Nome<br><input required name="nome" style="width:100%;padding:12px"></p><p>E-mail<br><input required type="email" name="email" style="width:100%;padding:12px"></p><p>Senha (mínimo 12 caracteres)<br><input required type="password" minlength="12" name="senha" style="width:100%;padding:12px"></p><button class="button">Criar administrador</button></form></main></body></html>
